
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b3lyp_mcm1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b3lyp_mcm1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.494328377779624e+00, -3.428310860943217e+00, -3.335849799664584e+00, -3.207861843355369e+00, -3.033653509804824e+00, -2.802181232108281e+00, -2.505001813509733e+00, -2.141473444997859e+00, -1.725280526777705e+00, -1.286290418077442e+00, -8.593176641369884e-01, -5.866916677055769e-01, -5.069430855352942e-01, -4.194968783230559e-01, -3.005785714247714e-01, -1.826501134674887e-01, -1.023346241197066e-01, -6.558946866335498e-02, -4.051586001339438e-02, -2.782832728170237e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


